14	func ParseRelativeDuration(s string) (time.Duration, error) {
15		s = strings.TrimSpace(strings.ToLower(s))
16		if s == "" {
17			return 0, fmt.Errorf("empty duration string")
18		}
19	
20		if strings.HasPrefix(s, "-") {
21			return 0, fmt.Errorf("negative durations are not allowed: %s", s)
22		}
23	
24		// Days: e.g. "14d"
25		if after, ok := strings.CutSuffix(s, "d"); ok {
26			days, err := strconv.Atoi(after)
27			if err != nil || days <= 0 {
28				return 0, fmt.Errorf("invalid day duration: %s", s)
29			}
30			return time.Duration(days) * 24 * time.Hour, nil
31		}
32	
33		// Weeks: e.g. "2w"
34		if after, ok := strings.CutSuffix(s, "w"); ok {
35			weeks, err := strconv.Atoi(after)
36			if err != nil || weeks <= 0 {
37				return 0, fmt.Errorf("invalid week duration: %s", s)
38			}
39			return time.Duration(weeks) * 7 * 24 * time.Hour, nil
40		}
41	
42		// Months: e.g. "3mo" or "1m" (when not followed by 's' for minutes)
43		if after, ok := strings.CutSuffix(s, "mo"); ok {
44			months, err := strconv.Atoi(after)
45			if err != nil || months <= 0 {
46				return 0, fmt.Errorf("invalid month duration: %s", s)
47			}
48			return time.Duration(months) * 30 * 24 * time.Hour, nil
49		}
50	
51		// Check if ending in 'm' could be month if it's "1m", "3m" and not e.g. "30m" where standard duration could apply.
52		// But in CLI horizon terms, "1m", "3m", "6m" almost always mean months.
53		// We disambiguate: if "m" is used, interpret as 30 days unless standard time.ParseDuration applies and has minutes.
54		// In our specification, "1m", "3m" are treated as 30-day months.
55		if after, ok := strings.CutSuffix(s, "m"); ok {
56			// If it's a pure integer before 'm', treat as months (e.g. 1m, 3m).
57			if val, err := strconv.Atoi(after); err == nil && val > 0 {
58				return time.Duration(val) * 30 * 24 * time.Hour, nil
59			}
60		}
61	
62		// Years: e.g. "1y"
63		if after, ok := strings.CutSuffix(s, "y"); ok {
64			years, err := strconv.Atoi(after)
65			if err != nil || years <= 0 {
66				return 0, fmt.Errorf("invalid year duration: %s", s)
67			}
68			return time.Duration(years) * 365 * 24 * time.Hour, nil
69		}
70	
71		// Standard Go duration fallback (e.g. "48h", "72h")
72		d, err := time.ParseDuration(s)
73		if err != nil || d <= 0 {
74			return 0, fmt.Errorf("invalid duration format %q (expected e.g. 14d, 2w, 1m, 48h)", s)
75		}
76		return d, nil
77	}

